(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};
  try {
    // ① 元件库：先看新的「两种方法」说明
    [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库')?.click();
    await sleep(2400);
    const share = document.querySelector('.lib-share');
    out.shareBlock = !!share;
    out.shareTitle = share?.querySelector('h3')?.textContent || null;
    out.shareItems = share ? share.querySelectorAll('ol li').length : 0;
    out.shareMentionsBackup = (share?.innerText || '').includes('备份与恢复');
    out.cardsBefore = document.querySelectorAll('.lib-card').length;

    // ② 自己加一个元件
    document.querySelector('.lib-add')?.click();
    await sleep(900);
    const byLabel = (label) => {
      const field = [...document.querySelectorAll('.ce-field')].find((f) => (f.querySelector('.ce-label')?.textContent || '').trim().startsWith(label));
      return field?.querySelector('.ce-input');
    };
    setV(byLabel('名字'), '备份测试元件');
    setV(byLabel('它是干嘛的'), '专门用来验证备份带不带元件库');
    [...document.querySelectorAll('.ce-foot .ce-btn')].find((b) => b.textContent.includes('保存'))?.click();
    await sleep(2000);
    out.cardsAfterAdd = document.querySelectorAll('.lib-card').length;

    // ③ 回工具箱，打开备份弹层
    document.querySelector('.lib-crumb-link')?.click();
    await sleep(1800);
    [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '备份与恢复')?.click();
    await sleep(1200);
    out.modalTitle = document.querySelector('.bk-head h2')?.textContent || null;
    out.modalCards = [...document.querySelectorAll('.bk-card h3')].map((e) => e.textContent);
    out.modalMentionsLibrary = (document.querySelector('.bk-modal')?.innerText || '').includes('元件');

    // ④ 生成备份并拦下字节
    let captured = null;
    const orig = URL.createObjectURL.bind(URL);
    URL.createObjectURL = (b) => { captured = b; return orig(b); };
    [...document.querySelectorAll('.bk-btn')].find((b) => b.textContent.includes('生成备份'))?.click();
    for (let i = 0; i < 24 && !captured; i++) await sleep(500);
    URL.createObjectURL = orig;
    out.backupMsg = document.querySelector('.bk-msg')?.textContent || null;
    out.exported = !!captured;
    if (captured) {
      const buf = new Uint8Array(await captured.arrayBuffer());
      let bin = '';
      const chunk = 0x8000;
      for (let i = 0; i < buf.length; i += chunk) bin += String.fromCharCode(...buf.subarray(i, i + chunk));
      out.bytes = buf.length;
      out.b64 = btoa(bin);
    }
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
